const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M4 3v17h17M9 15V9m5 6V5m5 10v-4"/>',book:'<path d="M12 5C9 3 5 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1v15"/>',cube:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 10v9M3 8l9 5 9-5M8 5l9 5"/>',play:'<path d="m9 5 11 7-11 7V5Z"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m1 4a5 5 0 0 1 4 5v2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v5h5M8 12h8m-8 4h8"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="15" cy="17" r="3" fill="white"/>',external:'<path d="M14 3h7v7m0-7L10 14m0-10H3v17h17v-7"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',shield:'<path d="m12 2 9 4v7c-1 5-5 8-9 9-4-1-8-4-9-9V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',logout:'<path d="M10 3H3v18h7m5-14 5 5-5 5m-6-5h11"/>'};
const icon=n=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">${icons[n]||icons.file}</svg></span>`;
const S={admin:null,run:null,tab:'overview',id:null,review:null,session:null,reviewIndex:0,group:'subject',metric:'total',taskIndex:0,answerIndex:0,filter:'',polling:false};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
async function api(path,options={}){const headers={'Content-Type':'application/json',...options.headers};const r=await fetch(path,{...options,headers,body:options.body===undefined?undefined:JSON.stringify(options.body)});const b=await r.json();if(!r.ok)throw new Error(b.error||`请求失败 (${r.status})`);return b;}
function num(n,d=1){return n==null?'—':Number(n).toFixed(d);}
function date(t){return new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});}
function status(s){const map={ready:['待执行','gray'],running:['执行中','blue'],awaiting_human:['待人工评审','orange'],completed:['已完成','green'],needs_attention:['需处理异常','red'],interrupted:['执行已中断','red'],done:['已完成','green'],pending:['待执行','gray'],failed:['失败','red']};const x=map[s]||[s,'gray'];return `<span class="tag ${x[1]}">${s==='running'?'<span class="status-dot"></span>':''}${x[0]}</span>`;}
function empty(title,text,button=''){return `<div class="empty"><div class="empty-icon">${icon('file')}</div><h3>${title}</h3><p>${text}</p>${button}</div>`;}
function progress(n,total){return `<div class="progress-label"><span>${n} / ${total}</span><span>${total?Math.round(n/total*100):0}%</span></div><div class="bar-track"><div class="bar-fill" style="width:${total?n/total*100:0}%"></div></div>`;}
function markdown(text){let lines=esc(text).split('\n'),out='',table=[];function inline(s){return s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}function flush(){if(!table.length)return;out+='<div class="table-wrap"><table>';table.filter(l=>!/^\s*\|?[\s:|\-]+\|\s*$/.test(l)).forEach((l,i)=>{const cells=l.trim().replace(/^\||\|$/g,'').split('|');out+=`<tr>${cells.map(x=>`<${i===0?'th':'td'}>${inline(x.trim())}</${i===0?'th':'td'}>`).join('')}</tr>`;});out+='</table></div>';table=[];}
 for(const l of lines){if(/^\s*\|.*\|\s*$/.test(l)){table.push(l);continue;}flush();const h=l.match(/^#{1,6}\s+(.+)/);out+=h?`<h3>${inline(h[1])}</h3>`:`<div class="mdline ${/^\s*[-*] /.test(l)?'bullet':''}">${inline(l)}</div>`;}flush();return `<div class="prose">${out}</div>`;}
const brand=()=>`<a class="brand" href="/admin"><span class="brandmark">E</span><span>EduBench<small>教育大模型评测</small></span></a>`;
function go(tab='overview',id=null){history.pushState({},'',`/admin?tab=${tab}${id?'&id='+encodeURIComponent(id):''}`);S.tab=tab;S.id=id;S.filter='';loadAdmin();}
async function loadAdmin(quiet=false){try{S.admin=await api('/api/admin/state');if(S.id)S.run=await api(`/api/admin/runs/${S.id}`);else if(['analysis','report'].includes(S.tab)&&S.admin.runs.length){S.id=S.admin.runs[0].id;S.run=await api(`/api/admin/runs/${S.id}`);}else S.run=null;if(!quiet||!$('#modal-root').innerHTML)renderAdmin();}catch(e){if(quiet)return;$('#app').innerHTML=`<div class="review-login"><h1>无法加载管理端</h1><p>${esc(e.message)}</p><a class="linkbtn" href="/review">进入人工评测</a></div>`;}}
function renderAdmin(){const analysis=['analysis','report'].includes(S.tab);const nav=analysis?'结果分析':'评测管理';$('#app').innerHTML=`<div class="layout"><aside class="sidebar">${brand()}<button class="sidebar-create primary" data-action="new-run">${icon('plus')} 新建评测</button><div class="navlabel">工作空间 · WORKSPACE</div><nav><a href="/admin" class="navitem ${!analysis?'active':''}">${icon('grid')}评测管理</a><a href="/admin?tab=analysis" class="navitem ${analysis?'active':''}">${icon('chart')}结果分析</a></nav><div class="sidebar-bottom"><a href="/review" target="_blank" class="navitem">${icon('users')}人工评测入口 ${icon('external')}</a><div class="workspace"><span class="avatar">E</span><div><p>教育模型评测工作台</p><small><span class="status-dot"></span>本地持久化 · DEMO</small></div></div></div></aside><header class="topbar"><div>工作台<span class="sep">/</span><strong>${nav}</strong></div><div class="top-actions"><span><span class="status-dot"></span>本地服务已连接</span><a href="/review" target="_blank" class="linkbtn small">人工评测 ${icon('external')}</a></div></header><main class="main">${analysis?analysisPage():S.tab==='run'?runPage():managementPage()}<div class="footer-line"><span>EduBench · 让教育 AI 的能力，变得可衡量</span><span>真实调用 / 统一标准 / 匿名评审</span></div></main></div>`;}
function managementPage(){const titles={overview:['Hi，欢迎来到 EduBench','让每一份 AI 教学内容，都经过真实、专业的评价。'],benchmark:['Benchmark 任务库','统一管理教学任务，让每个模型接受同样的测试。'],models:['模型与 API 配置','连接被测模型与独立 Judge，开始真实评测。'],rules:['评价维度与评分规则','统一五个评价维度，结合机器检查与教师专业判断。'],personnel:['评测人员管理','维护评测人员姓名，在任务详情中指定参与人员。']};const [title,desc]=titles[S.tab]||titles.overview;return `<div class="page-title"><div><div class="eyebrow">教育大模型评测工作台</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${S.tab==='personnel'?`<button class="primary" data-action="add-person">${icon('plus')} 添加评测人员</button>`:S.tab==='benchmark'?`<button data-action="import">${icon('plus')} 导入 Benchmark</button>`:S.tab==='rules'?`<button data-action="edit-rules">${icon('settings')} 编辑评分规则</button>`:`<button class="primary" data-action="new-run">${icon('plus')} 创建评测任务</button>`}</div></div><div class="tabs">${[['overview','评测任务'],['benchmark','Benchmark 任务库'],['models','模型配置'],['rules','评分规则'],['personnel','评测人员']].map(([t,n])=>`<a href="/admin?tab=${t}" class="tab ${S.tab===t?'active':''}">${n}</a>`).join('')}</div>${S.tab==='benchmark'?benchmarkPage():S.tab==='models'?modelsPage():S.tab==='rules'?rulesPage():S.tab==='personnel'?personnelPage():overviewPage()}`;}
function overviewPage(){const {runs,benchmarks,models}=S.admin;const totalQueries=benchmarks.reduce((s,b)=>s+b.cases.length,0);const stats=[['Benchmark Query',totalQueries,'条','已预置 PRD 的 9 条标准化任务','book'],['被测模型',models.filter(m=>m.role==='tested').length,'个','Doubao / DeepSeek / GLM','cube'],['评测批次',runs.length,'次',`${runs.filter(r=>r.active).length} 个执行中 · ${runs.filter(r=>r.status==='completed').length} 个已完成`,'play'],['人工评分',runs.reduce((s,r)=>s+r.progress.human,0),'组','已完成全体已分配评测人员的输出数','users']];return `<section class="launch-panel"><div class="launch-heading"><span class="launch-dot"></span><span>从一组真实教学任务，开始评测</span><span class="tag green">Benchmark 已就绪</span></div><p>9 条标准化 Query，覆盖教学设计、讲解与习题、课件与教学资源。<br>选择测试集，让三个模型在同一标准下接受检验。</p><div class="launch-bottom"><div class="launch-chips"><button data-action="go-benchmark">${icon('book')} 基础教育 · 9 Queries</button><button data-action="configure">${icon('cube')} 豆包 / DeepSeek / GLM</button><button data-action="go-rules">${icon('shield')} 机评 + 人工盲评</button></div><button class="launch-start" data-action="new-run" aria-label="创建评测任务">${icon('arrow')}</button></div></section><div class="stats">${stats.map(([n,v,u,note,i])=>`<div class="stat"><div class="stat-top">${n}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${v}<small>${u}</small></div><div class="stat-note">${note}</div></div>`).join('')}</div><div class="intro"><div class="intro-icon">${icon('shield')}</div><div><h3>同一套教学任务，更可信的模型对比</h3><p>三家模型独立生成，Qwen3.8-Max 按统一标准完成两维机评；教师匿名评审三项教学能力，共同形成最终综合得分。</p></div><div class="actions"><button class="small" data-action="go-rules">查看评分标准 ${icon('arrow')}</button></div></div>${models.some(m=>!m.ready)?`<div class="notice">开始前还需完成 ${models.filter(m=>!m.ready).length} 个 API 配置。9 条 Benchmark 已就绪，填写真实 model ID 与密钥后即可启动。<a href="/admin?tab=models"> 前往配置 →</a></div>`:''}<section class="card"><div class="card-header"><div><h2>评测任务 <span class="count">${runs.length}</span></h2><p>查看模型调用、自动评分与人工评审的完整进度</p></div><button class="small ghost" data-action="refresh">${icon('refresh')} 刷新</button></div>${runs.length?`<div class="table-wrap"><table><thead><tr><th>任务名称</th><th>创建时间</th><th>状态</th><th>模型生成 / 机评</th><th>人工评审</th><th>操作</th></tr></thead><tbody>${runs.map(r=>`<tr><td><a href="/admin?tab=run&id=${r.id}"><strong>${esc(r.name)}</strong></a><div class="subtext">${esc(r.modelNames.join(' · '))}</div></td><td class="no-wrap">${date(r.created)}</td><td>${status(r.status)}</td><td>${r.progress.generated} / ${r.progress.total} <span class="muted">·</span> ${r.progress.judged} / ${r.progress.total}</td><td>${progress(r.progress.human,r.progress.total)}<div class="subtext">${r.reviewerCount} 位已分配评测人员</div></td><td><button class="small ghost" data-action="open-run" data-id="${r.id}">查看详情 →</button><button class="small" data-action="assign-people" data-id="${r.id}">分配人员</button></td></tr>`).join('')}</tbody></table></div>`:empty('创建第一项教育模型评测','9 条标准化教学任务已经准备好。<br>配置模型 API，启动一次真实的横向评测。','<button class="primary small" data-action="new-run">创建评测任务</button>')}</section><section class="card"><div class="card-header"><h2>标准化评测流程</h2><span class="helper">机评 40% ＋ 人评 60%</span></div><div class="steps">${[['01','加载 Benchmark','统一 9 条教学任务'],['02','三个模型调用','并行采集真实输出'],['03','Judge 自动评分','核对并冻结逐题标准'],['04','人工匿名盲评','三维评分 · 多人独立'],['05','综合结果分析','加权得分与模型对比']].map(([n,t,d],i)=>`<div class="step"><span class="step-num">${n}</span><div>${t}<small>${d}</small></div></div>${i<4?'<span class="step-arrow">›</span>':''}`).join('')}</div></section>`;}
function benchmarkPage(){return S.admin.benchmarks.map(b=>`<section class="card"><div class="card-header"><div><h2>${icon('book')}${esc(b.name)} <span class="count">${b.cases.length} QUERIES</span></h2><p>教学设计 / 讲解与习题 / 课件与教学资源 · 三种 Query 类型</p></div><div class="actions"><button class="small ghost" data-action="rename-bench" data-id="${b.id}">重命名</button><button class="small" data-action="download-bench" data-id="${b.id}">${icon('download')} JSON</button><button class="small" data-action="add-case" data-bench="${b.id}">添加 Query</button><button class="small danger ghost" data-action="delete-bench" data-id="${b.id}">删除</button></div></div><div class="table-wrap"><table><thead><tr><th>任务 ID</th><th>任务名称</th><th>学科 / 学段</th><th>教学场景</th><th>Query 类型</th><th>操作</th></tr></thead><tbody>${b.cases.map(c=>`<tr><td><span class="tag gray">${esc(c.id)}</span></td><td><strong>${esc(c.title)}</strong></td><td>${esc(c.subject)}<div class="subtext">${esc(c.stage)}</div></td><td>${esc(c.category)}</td><td><span class="tag ${c.queryType==='多约束任务型'?'orange':c.queryType==='明确任务型'?'blue':''}">${esc(c.queryType)}</span></td><td class="no-wrap"><button class="small ghost" data-action="case" data-id="${esc(c.id)}" data-bench="${b.id}">查看 / 编辑</button></td></tr>`).join('')}</tbody></table></div></section>`).join('')||empty('暂无 Benchmark','导入 JSON 或 CSV 格式的测试集即可使用。');}
function modelsPage(){return `<div class="notice info">请填写实际可调用的 model ID 与密钥。下方预置官方服务常用地址，需与你的账号区域及接口协议核对；连接测试会发出一次真实请求并产生对应费用。密钥仅保存在服务端，不发送给评测人员。</div><div class="grid2">${S.admin.models.map((m,i)=>`<section class="card model-card"><div class="model-head"><span class="model-logo" style="background:${['#eeecfb','#eaf2fc','#edf5f1','#fff2e6'][i]};color:${['#8070ce','#588acc','#549880','#c79c62'][i]}">${{doubao:'D',deepseek:'D',glm:'G',qwen:'Q'}[m.id]}</span><div><h3>${esc(m.name)}</h3><small>${esc(m.provider)} · ${m.role==='judge'?'独立评测模型 / Judge':'被测模型'}</small></div><span class="tag ${m.connection?.ok?'green':m.connection?.ok===false?'red':'orange'}">${m.connection?.ok?'已验证':m.connection?.ok===false?'连接异常':m.ready?'已配置 · 待验证':'待配置'}</span></div><div class="model-data"><span>Model ID</span><span>${esc(m.model||'尚未填写')}</span><span>API 地址</span><span>${esc(m.baseUrl)}</span><span>API 密钥</span><span>${m.hasKey?'•••••••• · 已保存':'未配置'}</span><span>调用参数</span><span>temperature ${m.temperature} · max tokens ${m.maxTokens}</span></div>${m.connection?.ok===false?`<div class="notice error">${esc(m.connection.error)}</div>`:''}${m.role==='judge'?'<div class="helper" style="margin-bottom:17px">仅评需求满足度与输出完整性；不参与模型排名。</div>':''}<div class="actions"><button class="small" data-action="model" data-id="${m.id}">${icon('settings')} 配置 API</button><button class="small ghost" data-action="test-model" data-id="${m.id}" ${!m.ready?'disabled':''}>${icon('play')} 测试连接</button></div></section>`).join('')}</div><p class="footnote">三个被测模型默认使用相同温度与输出长度。若自行调整，请参考任务详情中冻结的实际参数；已创建任务不会随配置修改而改变。</p>`;}
function rulesPage(){const ds=S.admin.dimensions;return `<div class="intro"><div class="intro-icon">${icon('chart')}</div><div><h3>每一分，都对应明确的评价依据</h3><p>综合得分 = Σ（维度平均分 × 维度权重）÷ 3 × 100。同一输出先平均多位评审的分数，再对各 Query 等权平均。</p></div></div>${['auto','human'].map(kind=>`<section class="card"><div class="card-header"><h2>${kind==='auto'?icon('cube')+'自动机评':icon('users')+'人工盲评'} <span class="count">${ds.filter(d=>d.kind===kind).reduce((s,d)=>s+d.weight,0)}%</span></h2><span class="helper">统一 1—3 分制</span></div><div class="table-wrap"><table><thead><tr><th style="width:190px">评价维度</th><th>1 分 · 较差</th><th>2 分 · 合格</th><th>3 分 · 优秀</th><th>权重</th></tr></thead><tbody>${ds.filter(d=>d.kind===kind).map(d=>`<tr><td><strong>${esc(d.name)}</strong><div class="subtext">${esc(d.focus)}</div></td>${d.levels.map(l=>`<td>${esc(l)}</td>`).join('')}<td><span class="tag">${d.weight}%</span></td></tr>`).join('')}</tbody></table></div></section>`).join('')}<div class="notice info">Judge 对每条 Query 先生成检查项，再单独核对并冻结标准，统一应用于三个模型。最终排名仅在所有 Query 的机评与所有已分配评测人员评分齐全后展示；中途数据保留为进度与维度观察值。</div>`;}
function runSelect(){return `<select id="run-select" aria-label="选择评测任务" style="max-width:330px">${S.admin.runs.map(r=>`<option value="${r.id}" ${S.id===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`;}
function runPage(){const r=S.run;if(!r)return empty('任务不存在','请选择有效的评测任务');const p=r.progress;return `<div class="page-title"><div><div class="eyebrow"><a href="/admin">评测管理</a> / 任务详情</div><h1>${esc(r.name)}</h1><p>${date(r.created)} · ${esc(r.snapshot.benchmarkName)} · ${status(r.status)}</p></div><div class="actions"><button data-action="assign-people" data-id="${r.id}">${icon('users')} 分配人员</button><button data-action="share" data-id="${r.id}">评测链接</button><button class="primary" data-action="analyze" data-id="${r.id}">${icon('chart')} 结果分析</button></div></div>${r.description?`<p class="helper">${esc(r.description)}</p>`:''}<section class="card"><div class="run-progress">${[['模型生成',p.generated],['Judge 自动评分',p.judged],['人工评审',p.human]].map(([n,v])=>`<div><h3>${n}</h3><strong>${v}</strong><small> / ${p.total}</small>${progress(v,p.total)}</div>`).join('')}</div></section><p class="helper" style="margin:0 0 18px">逐题评分标准：${r.rubrics.filter(x=>x.status==='done').length} / ${r.rubrics.length} 已核对冻结${r.rubrics.some(x=>x.status==='running')?' · 正在生成或核对':''}</p>${r.rubrics.some(x=>x.status==='failed')?`<div class="notice error">评分标准需处理：${r.rubrics.filter(x=>x.status==='failed').map(x=>`${esc(x.caseId)} · ${esc(x.error)}`).join('<br>')}</div>`:''}${r.active?'<div class="notice info">真实 API 调用中，页面每 3 秒更新。关闭页面不影响服务端执行；请保持本地服务运行。</div>':r.status==='needs_attention'||r.status==='interrupted'?'<div class="notice error">存在调用失败或未完成步骤。查看下方具体错误，确认配置后可重试；成功输出与已冻结标准会保留。</div>':''}<div class="actions no-print" style="margin-bottom:20px"><button class="small" data-action="retry" data-id="${r.id}" ${r.active?'disabled':''}>${icon('refresh')} 重试失败 / 继续未完成步骤</button><button class="small ghost" data-action="snapshot">查看本次配置快照</button><button class="small danger ghost" data-action="delete-run" data-id="${r.id}" ${r.active?'disabled':''}>删除任务</button></div>${reviewersCard(r)}<section class="card"><div class="card-header"><div><h2>模型输出与评分 <span class="count">${p.total} CASES</span></h2><p>点击详情可查看完整输出、逐题评分标准、机评依据与人工记录</p></div></div><div class="table-wrap"><table><thead><tr><th>Query / 任务</th><th>模型</th><th>生成</th><th>自动评分</th><th>耗时 / Token</th><th>人工评审</th><th>详情</th></tr></thead><tbody>${r.outputs.map(o=>{const c=r.snapshot.cases.find(c=>c.id===o.caseId),m=r.snapshot.models.find(m=>m.id===o.modelId);const row=r.report.rows.find(x=>x.id===o.id);return `<tr><td><strong>${esc(c.id)}</strong><div class="subtext">${esc(c.title)}</div></td><td>${esc(m.name)}</td><td>${status(o.generationStatus)}${o.error?`<div class="subtext danger">${esc(o.error.slice(0,90))}</div>`:''}</td><td>${status(o.judgeStatus)}${o.autoScore?`<div class="subtext">需求 ${o.autoScore.fulfillment.score} · 完整 ${o.autoScore.completeness.score}</div>`:''}${o.judgeError?`<div class="subtext danger">${esc(o.judgeError.slice(0,90))}</div>`:''}</td><td>${o.latencyMs==null?'—':num(o.latencyMs/1000)+'s'}<div class="subtext">${o.usage?.total??'—'} tokens</div></td><td>${row.humanCount} / ${r.reviewers.length||'—'} 位</td><td><button class="small ghost" data-action="output" data-id="${o.id}">查看 →</button></td></tr>`;}).join('')}</tbody></table></div></section>`;}
function personnelPage(){const people=S.admin.personnel;return `<section class="card"><div class="card-header"><div><h2>${icon('users')}评测人员 <span class="count">${people.length} 位</span></h2><p>姓名为当前 Demo 的登录标识。修改姓名后，已有分配和评分仍归属于同一人员。</p></div><button data-action="add-person">添加人员</button></div>${people.length?`<div class="table-wrap"><table><thead><tr><th>姓名</th><th>已分配批次</th><th>添加时间</th><th>操作</th></tr></thead><tbody>${people.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${p.assignedRuns}</td><td>${date(p.created)}</td><td><button class="small" data-action="edit-person" data-id="${p.id}">编辑姓名</button></td></tr>`).join('')}</tbody></table></div>`:empty('添加第一位评测人员','添加后，在评测任务详情中分配人员。','<button class="primary" data-action="add-person">添加人员</button>')}</section>`;}
function personModal(id){const p=S.admin.personnel.find(p=>p.id===id);modal(p?'编辑评测人员':'添加评测人员',`<form id="person-form" data-id="${p?.id||''}">${field('评测人员姓名','name',p?.name||'','text','required maxlength="40" placeholder="请输入唯一姓名"')}<p class="helper">评测人员使用此姓名登录；不需要密码。同名人员请添加可区分的后缀。</p></form>`,modalButtons('person-form'));}
async function assignmentModal(id){const r=S.run?.id===id?S.run:await api(`/api/admin/runs/${id}`);const people=S.admin.personnel;modal('分配评测人员',`<p class="prose">${esc(r.name)} · ${r.snapshot.cases.length} 条教学任务，每条包含 ${r.snapshot.models.length} 个匿名回答。Qwen 自动评分独立执行。</p>${people.length?`<form id="assignment-form" data-id="${id}"><div class="person-options">${people.map(p=>`<label><input type="checkbox" name="personIds" value="${p.id}" ${r.reviewers.some(v=>v.personId===p.id)?'checked':''}><span>${esc(p.name)}</span></label>`).join('')}</div><p class="helper">取消勾选会收回该人员访问权限；历史评分保留可查，但不计入当前汇总。重新分配可恢复原进度。</p></form>`:empty('请先添加评测人员','在评测人员管理中添加姓名后即可分配。')}`,people.length?modalButtons('assignment-form','保存分配'):'<button data-action="close">关闭</button><button class="primary" data-action="go-personnel">添加评测人员</button>');}
function reviewersCard(r){return `<section class="card"><div class="card-header"><div><h2>${icon('users')}人工评测进度 <span class="count">${r.reviewers.length} 位已分配</span></h2><p>每位人员 ${r.snapshot.cases.length} 条任务 · 每条 ${r.snapshot.models.length} 个匿名回答 · 点击查看未完成项与评分记录</p></div><button class="small" data-action="assign-people" data-id="${r.id}">分配人员</button></div>${r.reviewers.length?`<div class="table-wrap"><table><thead><tr><th>姓名</th><th>完成任务</th><th>已评分回答</th><th>三维均分 / 3</th><th>最近提交</th><th>进度 / 操作</th></tr></thead><tbody>${r.reviewers.map(v=>`<tr><td><strong>${esc(v.name)}</strong></td><td>${v.taskDone} / ${v.taskTotal}</td><td>${v.done} / ${v.total}</td><td>${['accuracy','suitability','utility'].map(k=>num(v.values[k],2)).join(' / ')}</td><td>${v.lastSubmitted?date(v.lastSubmitted):'尚未提交'}</td><td>${progress(v.done,v.total)}<button class="small ghost" data-action="person-progress" data-id="${v.id}">未完成任务 / 评分记录 →</button></td></tr>`).join('')}</tbody></table></div>`:empty('尚未分配评测人员','先在评测人员管理添加姓名，再指定本批次参与人员。')} ${(r.allReviewers||[]).some(v=>!v.active)?`<details class="card-body"><summary>已取消分配人员的历史记录</summary>${r.allReviewers.filter(v=>!v.active).map(v=>`<button class="small ghost" data-action="person-progress" data-id="${v.id}">${esc(v.name)} · ${v.done} 份评分 →</button>`).join('')}</details>`:''}</section>`;}
function personProgressModal(id){const r=S.run,v=r.allReviewers.find(v=>v.id===id);const ds=r.snapshot.dimensions.filter(d=>d.kind==='human');modal(`${v.name} · 评测明细`,`${!v.active?'<div class="notice">此人员已取消分配，历史评分不计入当前汇总。</div>':''}<p class="prose">完成 ${v.taskDone}/${v.taskTotal} 条任务，已评分 ${v.done}/${v.total} 个回答。</p><div class="section-title">未完成任务</div>${v.tasks.filter(t=>t.done<t.total).map(t=>`<div class="pending-task"><strong>${esc(t.id)} · ${esc(t.title)}</strong><p class="helper">待评分：${t.answers.filter(a=>!a.submitted).map(a=>`${esc(r.snapshot.models.find(m=>m.id===a.modelId).name)}${a.generationStatus==='done'?'':'（输出未就绪）'}`).join('、')}</p></div>`).join('')||'<p class="saved">全部任务已完成</p>'}<div class="section-title">逐条评分记录</div><div class="table-wrap"><table><thead><tr><th>任务 / 模型</th>${ds.map(d=>`<th>${esc(d.name)}</th>`).join('')}<th>提交时间</th><th>意见</th></tr></thead><tbody>${r.reviews.filter(x=>x.reviewerId===id).map(x=>{const o=r.outputs.find(o=>o.id===x.outputId);return `<tr><td><button class="small ghost" data-action="output" data-id="${o.id}">${esc(o.caseId)} · ${esc(r.snapshot.models.find(m=>m.id===o.modelId).name)}</button></td>${ds.map(d=>`<td>${x.scores[d.id]}</td>`).join('')}<td>${date(x.updated)}</td><td>${esc(x.note||'—')}</td></tr>`;}).join('')}</tbody></table></div>`,`<button data-action="close">关闭</button>`,true);}
function scoreTable(r){return `<div class="table-wrap"><table class="metric-table"><thead><tr><th>排名 / 模型</th>${r.report.dimensions.map(d=>`<th>${esc(d.name)}<br><span class="helper">${d.weight}% · ${d.kind==='auto'?'机评':'人评'}</span></th>`).join('')}<th>综合得分 / 100</th><th>覆盖情况</th></tr></thead><tbody>${[...r.report.models].sort((a,b)=>(a.rank??99)-(b.rank??99)).map(m=>`<tr><td><span class="rank">${m.rank??'—'}</span> <strong>${esc(m.name)}</strong></td>${r.report.dimensions.map(d=>`<td>${num(m.values[d.id],2)}</td>`).join('')}<td><span class="score-large">${num(m.total)}</span></td><td><span class="tag ${m.complete?'green':'orange'}">${m.complete?'数据齐全':'待完成'}</span><div class="subtext">机评 ${m.autoDone}/${m.expected} · 人评 ${m.humanDone}/${m.expected}</div></td></tr>`).join('')}</tbody></table></div>`;}
function analysisPage(){const reportMode=S.tab==='report';const r=S.run;if(!r)return `<div class="page-title"><div><div class="eyebrow">RESULTS & INSIGHTS</div><h1>结果分析</h1><p>汇总机器评分与人工判断，观察模型在真实教学任务中的表现。</p></div></div><div class="card">${empty('尚无评测结果','创建评测任务并完成真实调用后，结果将在这里汇总。','<button class="primary" data-action="new-run">创建评测任务</button>')}</div>`;
return `<div class="page-title no-print"><div><div class="eyebrow">RESULTS & INSIGHTS</div><h1>${reportMode?'模型评测报告':'结果分析'}</h1><p>统一任务 · 五维评价 · 真实数据追溯</p></div><div class="actions">${runSelect()}<button data-action="download-results">${icon('download')} 原始数据</button><button class="primary" data-action="${reportMode?'print':'report'}">${icon('file')} ${reportMode?'保存为 PDF':'导出评测报告'}</button></div></div>${reportMode?`<div class="report-head"><div class="eyebrow">EDUBENCH / EVALUATION REPORT</div><h1>${esc(r.name)}</h1><p>${esc(r.snapshot.benchmarkName)} · ${r.snapshot.cases.length} Queries · ${r.snapshot.models.length} Models<br>创建于 ${date(r.created)} · 报告生成于 ${new Date().toLocaleString('zh-CN')}<br>独立 Judge：${esc(r.snapshot.judge.model)}</p></div>`:''}${!r.report.complete?'<div class="notice">评测尚未全部完成。维度均分仅用于观察当前进展；缺失分数不补零，最终综合得分与排名暂不显示。所有已分配评测人员须完成全部输出。</div>':'<div class="notice info">机评与全体已分配评测人员评分已齐全。每个 Query 等权平均，多人评分先在同一输出内取均值，再按五维权重计算总分。</div>'}<section class="card"><div class="card-header"><h2>模型综合得分与五维对比</h2><span class="helper">维度满分 3 · 综合满分 100</span></div>${scoreTable(r)}</section><div class="grid2"><section class="card"><div class="card-header"><h2>综合表现</h2><span class="helper">100 分制</span></div><div class="card-body">${r.report.models.map(m=>`<div class="compare-row"><span>${esc(m.name)}</span><div class="compare-bar"><div style="width:${m.total??0}%"></div></div><strong>${m.total===null?'待完成':num(m.total)}</strong></div>`).join('')}</div></section><section class="card"><div class="card-header"><h2>执行与采集概况</h2></div><div class="card-body"><div class="model-data" style="margin:0"><span>模型生成</span><span>${r.progress.generated} / ${r.progress.total}</span><span>Judge 评分</span><span>${r.progress.judged} / ${r.progress.total}</span><span>人工提交</span><span>${r.reviews.filter(x=>r.reviewers.some(v=>v.id===x.reviewerId)).length} 份有效评分 · ${r.reviewers.length} 位已分配人员</span><span>被测 Token</span><span>${r.report.models.reduce((s,m)=>s+m.tokens,0)}（供应商实际返回值）</span></div></div></section></div>${groupTable(r,reportMode)}${insights(r)}${reportMode?reportDetails(r):reviewersCard(r)}`;}
function groupTable(r,all=false){const keys=all?['category','queryType','subject']:[S.group];const metric=S.metric;return keys.map(key=>`<section class="card"><div class="card-header"><div><h2>${{category:'教学场景',queryType:'Query 类型',subject:'学科'}[key]}表现对比</h2><p>${metric==='total'?'综合分仅在该分组评分齐全时显示':'维度均分基于当前已提交评分，缺失不补零'} · 三个模型横向对比</p></div><div class="actions">${all?'':`<select id="group-select" aria-label="对比分类">${[['subject','按学科'],['category','按教学场景'],['queryType','按 Query 类型']].map(([k,n])=>`<option value="${k}" ${key===k?'selected':''}>${n}</option>`).join('')}</select>`}<select class="metric-select" aria-label="对比评分维度"><option value="total" ${metric==='total'?'selected':''}>综合得分 / 100</option>${r.report.dimensions.map(d=>`<option value="${d.id}" ${metric===d.id?'selected':''}>${esc(d.name)} / 3</option>`).join('')}</select></div></div><div class="table-wrap"><table><thead><tr><th>分组</th>${r.report.models.map(m=>`<th>${esc(m.name)}</th>`).join('')}</tr></thead><tbody>${r.report.models[0].groups[key].map((g,i)=>`<tr><td>${esc(g.label)}</td>${r.report.models.map(m=>{const x=m.groups[key][i];return `<td>${num(metric==='total'?x.total:x.values[metric],2)} <span class="helper">${x.complete?'':'待完成'}</span></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`).join('');}
function insights(r){const scored=r.report.rows.filter(x=>x.total!==null&&x.fullReviews).sort((a,b)=>b.total-a.total);const disputed=r.report.rows.filter(x=>x.disputed);const errors=r.report.rows.filter(x=>x.error||x.judgeError);const named=o=>{const c=r.snapshot.cases.find(c=>c.id===o.caseId),m=r.snapshot.models.find(m=>m.id===o.modelId);return `<button class="small ghost" data-action="output" data-id="${o.id}">${esc(c.id)} · ${esc(m.name)} →</button>`;};return `<section class="card"><div class="card-header"><h2>模型表现简析</h2><span class="helper">按已保存分数自动归纳</span></div><div class="card-body">${r.report.models.map(m=>{const available=r.report.dimensions.filter(d=>m.values[d.id]!=null).sort((a,b)=>m.values[b.id]-m.values[a.id]);return `<p class="prose"><strong>${esc(m.name)}</strong>：${!available.length?'暂无评分，等待真实评测。':`当前较高维度为「${esc(available[0].name)}」（${num(m.values[available[0].id],2)}）；较低维度为「${esc(available.at(-1).name)}」（${num(m.values[available.at(-1).id],2)}）。${available.length>1&&Math.abs(m.values[available[0].id]-m.values[available.at(-1).id])<1e-9?' 各已评分维度当前相同。':''}${m.complete?'已完成本批次评测。':'数据尚不完整，暂不作最终结论。'}`}</p>`;}).join('')}<div class="divider"></div><div class="section-title">典型优秀案例 · 已完成案例中得分最高</div>${scored.length?named(scored[0])+`<span class="tag green">${num(scored[0].total)} 分</span>`:'<p class="helper">等待完整评分</p>'}<div class="section-title">典型问题案例 · 已完成案例中得分最低</div>${scored.length?named(scored.at(-1))+`<span class="tag orange">${num(scored.at(-1).total)} 分</span>`:'<p class="helper">等待完整评分</p>'}<div class="section-title">人评争议案例 · 同一维度相差 2 分</div>${disputed.length?disputed.map(named).join(''):'<p class="helper">暂无达到争议阈值的案例</p>'}<div class="section-title">调用失败案例</div>${errors.length?errors.map(named).join(''):'<p class="helper">暂无已记录的调用错误</p>'}<div class="divider"></div><p class="prose"><strong>综合评测结论：</strong>${r.report.complete?`本批次排名第一的模型为 ${esc(r.report.models.filter(m=>m.rank===1).map(m=>m.name).join('、'))}（${num([...r.report.models].sort((a,b)=>a.rank-b.rank)[0].total)} 分）。结论基于 ${r.snapshot.cases.length} 条 Query 与 ${r.reviewers.length} 位评审，不外推至其他教学场景。`:'本批次尚未具备完整数据，暂不生成最终选型结论。'}</p></div></section>`;}
function reportDetails(r){return `<section class="card"><div class="card-header"><h2>评测方法与评分依据</h2></div><div class="card-body prose"><p>相同 Query 分别提交给三家模型。Judge 逐题生成标准并单独核对，冻结后对三个匿名输出评分。人工评审按随机编码和固定随机顺序独立评审。</p><p>综合得分 = Σ（维度平均分 × 权重）÷ 3 × 100。多人评分先按同一输出取平均，再按 Query 等权汇总。机评 ${r.report.dimensions.filter(d=>d.kind==='auto').reduce((s,d)=>s+d.weight,0)}%，人评 ${r.report.dimensions.filter(d=>d.kind==='human').reduce((s,d)=>s+d.weight,0)}%。</p>${r.report.dimensions.map(d=>`<p><strong>${esc(d.name)} · ${d.weight}%</strong><br>${d.levels.map((l,i)=>`${i+1}分：${esc(l)}`).join('<br>')}</p>`).join('')}<p>使用浏览器的「保存为 PDF」打印目的地导出本报告。原始输出、逐题冻结标准与逐人评分可通过管理端「原始数据」下载追溯。</p></div></section><section class="card report-cases"><div class="card-header"><h2>逐 Case 评分记录与问题</h2></div><div class="card-body">${r.report.rows.map(o=>`<div style="margin-bottom:22px"><strong>${esc(o.caseId)} · ${esc(r.snapshot.models.find(m=>m.id===o.modelId).name)}</strong><p class="helper">${r.report.dimensions.map(d=>`${esc(d.name)} ${num(o.values[d.id],2)}`).join(' / ')} · 综合 ${num(o.total)}</p>${o.autoScore?`<p class="prose">需求满足度：${esc(o.autoScore.fulfillment.reason)}<br>输出完整性：${esc(o.autoScore.completeness.reason)}<br>问题：${esc(o.autoScore.issues.join('；')||'未记录')}</p>`:`<p class="helper">${esc(o.error||o.judgeError||'机评未完成')}</p>`}</div>`).join('')}</div></section>`;}
function modal(title,content,footer='',wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="ghost" data-action="close" aria-label="关闭">×</button></div><div class="modal-content"><div id="form-error" class="inline-error" role="alert"></div>${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>$('#modal-root input, #modal-root textarea, #modal-root select')?.focus(),30);}
let confirmResolve=null;
function closeModal(){if(confirmResolve){const resolve=confirmResolve;confirmResolve=null;resolve(false);}$('#modal-root').innerHTML='';}
function confirmAction(message){modal('确认操作',`<p class="prose">${esc(message)}</p>`,`<button data-action="close">取消</button><button class="primary" data-action="confirm-action">确认继续</button>`);return new Promise(resolve=>{confirmResolve=resolve;});}
const modalButtons=(form,label='保存')=>`<button data-action="close">取消</button><button class="primary" type="submit" form="${form}">${label}</button>`;
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
function modelModal(id){const m=S.admin.models.find(m=>m.id===id);modal(`配置 ${m.name}`,`<form id="model-form" data-id="${id}">${field('显示名称','name',m.name,'text','required')}<label class="field">API 协议<select name="protocol">${[['openai','Chat Completions'],['responses','Responses'],['gemini','Gemini 原生']].map(([id,label])=>`<option value="${id}" ${m.protocol===id?'selected':''}>${label}</option>`).join('')}</select></label>${field('Model ID · 供应商实际型号','model',m.model,'text','required placeholder="请填写账号可用的准确 model ID"')}${field('API Base URL · 不含 /responses、/chat/completions 等路径','baseUrl',m.baseUrl,'url','required')}${field(`API 密钥 ${m.hasKey?'· 已保存，留空则保留':''}`,'apiKey','','password','autocomplete="new-password" placeholder="仅保存到本机服务端"')}<div class="form-grid">${field('温度 Temperature','temperature',m.temperature,'number','required min="0" max="2" step="0.1"')}${field('输出 Token 上限','maxTokens',m.maxTokens,'number','required min="256" max="65536"')}</div>${field('请求超时（秒）','timeout',m.timeoutMs/1000,'number','required min="10" max="600"')}<div class="helper">协议：${{gemini:'Gemini generateContent',responses:'Responses',openai:'OpenAI 兼容 Chat Completions'}[m.protocol]}。默认三家被测模型使用一致参数。测试连接会实际调用模型。</div>${m.hasKey?'<label class="helper" style="display:flex;gap:8px;margin-top:14px;align-items:center"><input type="checkbox" name="clearKey" style="width:auto"> 清除已保存的密钥</label>':''}</form>`,modalButtons('model-form'));}
function newRun(){const ready=S.admin.models.every(m=>m.ready);modal('创建评测任务',`<form id="run-form">${!ready?'<div class="notice">模型配置尚未完成。请先在「模型配置」中补充准确型号及密钥；系统不会生成模拟结果。</div>':''}${field('任务名称','name',`基础教育模型评测 · ${new Date().toLocaleDateString('zh-CN')}`,'text','required maxlength="100"')}<label class="field">Benchmark 测试集<select name="benchmarkId" required>${S.admin.benchmarks.map(b=>`<option value="${b.id}">${esc(b.name)} · ${b.cases.length} 条</option>`).join('')}</select></label><label class="field">任务描述（选填）<textarea name="description" placeholder="记录本轮评测的目的与说明"></textarea></label><div class="section-title">本次参测模型</div><div class="task-meta">${S.admin.models.map(m=>`<span class="tag ${m.ready?'green':'orange'}">${esc(m.name)} · ${m.role==='judge'?'Judge':m.model||'待配置'}</span>`).join('')}</div><div class="notice info">首期 9 条 Query 将产生 27 次生成、18 次 Judge 标准生成与核对、27 次 Judge 评分（共 72 次 API 请求）。实际次数随测试集长度变化。启动会产生供应商费用；不会自动重试失败请求。</div><div class="helper">使用当前 Benchmark、模型参数、评分规则的冻结快照。创建后可在任务详情「分配人员」，指定每位人员完成本批次全部教学任务。Qwen 机评独立执行。</div></form>`,`<button data-action="close">取消</button>${ready?'<button class="primary" form="run-form" type="submit">创建并启动真实评测</button>':'<button class="primary" data-action="configure">前往模型配置</button>'}`);}
function caseModal(benchId,caseId){const b=S.admin.benchmarks.find(b=>b.id===benchId);const c=b.cases.find(c=>c.id===caseId)||{id:'',title:'',subject:'',stage:'',category:'教学设计',queryType:'明确任务型',query:'',background:'',requirements:''};modal(caseId?`${c.id} · 任务详情`:'添加 Query',`<form id="case-form" data-bench="${benchId}" data-id="${esc(caseId||'')}"><div class="form-grid">${field('任务 ID','id',c.id,'text','required')}${field('任务名称','title',c.title,'text','required')}</div><div class="form-grid">${field('学科','subject',c.subject,'text','required')}${field('教育阶段','stage',c.stage,'text','required')}</div><div class="form-grid"><label class="field">教学场景<select name="category">${['教学设计','讲解与习题','课件与教学资源'].map(x=>`<option ${x===c.category?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Query 类型<select name="queryType">${['开放模糊型','明确任务型','多约束任务型'].map(x=>`<option ${x===c.queryType?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field">任务背景<textarea name="background" style="min-height:65px">${esc(c.background)}</textarea></label><label class="field">标准化 Query · 发送给三个模型的完整原文<textarea name="query" required style="min-height:300px">${esc(c.query)}</textarea></label><label class="field">任务要求 · 用于评审与 Judge 对照<textarea name="requirements" style="min-height:150px">${esc(c.requirements)}</textarea></label><div class="helper">PRD 首期任务使用 Query 原文作为完整任务要求。修改只影响后续新任务，已有评测保留创建时快照。</div></form>`,`${caseId?`<button class="danger ghost" data-action="delete-case" data-bench="${benchId}" data-id="${esc(caseId)}">删除此 Query</button>`:''}${modalButtons('case-form')}`,true);}
function importModal(){modal('导入 Benchmark',`<form id="import-form">${field('测试集名称','name','','text','required placeholder="为测试集命名"')}<label class="field">上传 JSON / CSV<input name="file" type="file" accept=".json,.csv" required></label><div class="notice info">JSON 可为 Query 数组或 { "cases": [...] }；CSV 第一行为字段名，支持引号内换行。必须包含下方七个字段。</div><div class="code-block">id, title, subject, stage, category, queryType, query\n\n可选：background, requirements, scenario</div><p class="helper">可从现有 Benchmark 下载 JSON 作为模板。导入后会先校验必填项与任务 ID，不会覆盖已有测试集。</p></form>`,modalButtons('import-form','校验并导入'));}
function rulesModal(){modal('编辑评分标准',`<form id="rules-form">${S.admin.dimensions.map(d=>`<div class="rating-card"><div class="rating-title">${d.kind==='auto'?'机评':'人评'} · ${esc(d.name)}</div><div class="form-grid">${field('维度名称',d.id+'_name',d.name,'text','required')}${field('权重（%）',d.id+'_weight',d.weight,'number','required min="0.1" max="99" step="0.1"')}</div>${field('评价重点',d.id+'_focus',d.focus)}${d.levels.map((l,i)=>`<label class="field">${i+1} 分 · ${['较差','合格','优秀'][i]}<textarea name="${d.id}_${i}" required style="min-height:70px">${esc(l)}</textarea></label>`).join('')}</div>`).join('')}<div class="helper">五项权重之和必须为 100%。保存后的规则应用于新建任务。</div></form>`,modalButtons('rules-form'),true);}
function outputModal(id){const r=S.run,o=r.outputs.find(o=>o.id===id);const c=r.snapshot.cases.find(c=>c.id===o.caseId);const m=r.snapshot.models.find(m=>m.id===o.modelId);const rubric=r.rubrics.find(x=>x.caseId===o.caseId);const rs=r.reviews.filter(x=>x.outputId===id);modal(`${c.id} · ${m.name}`,`<div class="task-meta"><span class="tag">${esc(c.subject)}</span><span class="tag gray">${esc(c.stage)}</span>${status(o.generationStatus)}${status(o.judgeStatus)}</div>${o.error?`<div class="notice error">生成错误：${esc(o.error)}</div>`:''}${o.judgeError?`<div class="notice error">机评错误：${esc(o.judgeError)}</div>`:''}<details><summary>任务背景与完整 Query</summary><p class="helper">${esc(c.background)}</p><div class="query">${esc(c.query)}</div></details><div class="section-title">模型完整输出 ${o.latencyMs?`· ${num(o.latencyMs/1000)} 秒 · ${o.usage?.total??'未知'} Token`:''}</div><div class="scroll-content">${o.content?markdown(o.content):'<p class="helper">暂无成功输出</p>'}</div><div class="section-title">Judge 自动评分</div>${o.autoScore?`<div class="score-pills"><div class="score-pill"><strong>${o.autoScore.fulfillment.score}</strong>需求满足度</div><div class="score-pill"><strong>${o.autoScore.completeness.score}</strong>输出完整性与规范性</div></div><p class="prose">${esc(o.autoScore.fulfillment.reason)}</p><p class="prose">${esc(o.autoScore.completeness.reason)}</p><div class="notice info">问题记录：${esc(o.autoScore.issues.join('；')||'无')}</div>`:'<p class="helper">等待 Judge 评分</p>'}<details><summary>查看冻结评分标准、草案与核对记录</summary>${rubric?.error?`<div class="notice error">${esc(rubric.error)}</div>`:''}<pre class="code-block">${esc(JSON.stringify({status:rubric?.status,draft:rubric?.draft,frozen:rubric?.rubric,metadata:rubric?.meta},null,2))}</pre></details><div class="section-title">人工评分记录 · ${rs.length} 位</div>${rs.length?`<table><thead><tr><th>评审</th><th>知识准确</th><th>教学适配</th><th>实用创新</th><th>意见</th><th>提交时间</th></tr></thead><tbody>${rs.map(s=>`<tr><td>${esc(r.allReviewers.find(v=>v.id===s.reviewerId)?.name)}${r.allReviewers.find(v=>v.id===s.reviewerId)?.active?'':'（已取消分配）'}</td><td>${s.scores.accuracy}</td><td>${s.scores.suitability}</td><td>${s.scores.utility}</td><td>${esc(s.note||'—')}</td><td>${date(s.updated)}</td></tr>`).join('')}</tbody></table>`:'<p class="helper">暂无人工评分</p>'}`,`<button data-action="close">关闭</button>`,true);}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function share(){const url=`${location.origin}/review?run=${S.run.token}`;modal('邀请人工评审',`<p class="prose">请先通过「分配人员」指定评测人员，再分享链接。只有已分配姓名可以进入本批次，共 ${S.run.snapshot.cases.length} 条任务，每条 ${S.run.snapshot.models.length} 个匿名回答。</p><label class="field">评测链接<input id="share-url" readonly value="${esc(url)}"></label><div class="notice info">同一局域网内使用时，请将 localhost 替换为这台电脑的局域网 IP，并保持服务运行。远程评审只能访问评测端，管理接口仅限本机。</div><p class="helper">Demo 使用管理员登记的唯一姓名登录。同名会恢复同一份进度，适用于受信任的小范围评审。</p>`,`<button data-action="close">关闭</button><button class="primary" data-action="copy-share">复制链接</button>`);}
// Review entrance: only the dedicated public endpoints are requested here.
async function loadReview(){S.reviewRunToken=new URLSearchParams(location.search).get('run');const saved=JSON.parse(localStorage.getItem('edubench-review')||'null');
 if(saved&&(!S.reviewRunToken||saved.runToken===S.reviewRunToken)){S.review=saved;await refreshReview();}else await reviewLogin();}
function reviewFrame(content,logged=false){return `<div class="review-shell"><header class="review-header">${brand()}<div class="actions">${logged?`<span class="muted">${icon('users')} ${esc(S.review.name)}</span><button class="small ghost" data-action="review-logout">切换评审 ${icon('logout')}</button>`:'<span class="tag">人工匿名评测</span>'}</div></header>${content}</div>`;}
async function reviewLogin(){S.session=null;$('#app').innerHTML=reviewFrame(`<div class="review-login"><div class="intro-icon">${icon('users')}</div><div class="eyebrow" style="margin-top:25px">HUMAN EVALUATION</div><h1>用专业判断，衡量教学价值</h1><p>输入管理员为你登记的姓名，进入已分配任务。<br>每条任务包含三个匿名模型回答，请分别独立评分。</p><form id="join-form">${S.reviewRunToken?`<input type="hidden" name="runToken" value="${esc(S.reviewRunToken)}">`:''}${field('评测人员姓名','name','','text','required maxlength="40" autocomplete="name" placeholder="请输入管理员登记的姓名"')}<div id="join-error" class="inline-error" role="alert"></div><button class="primary" style="width:100%" type="submit">进入我的评测任务 ${icon('arrow')}</button></form><p class="helper">仅可查看管理员已分配给你的任务。同名恢复原进度，评分提交后自动保存。</p></div>`);}
const reviewHeaders=()=>({Authorization:`Bearer ${S.review.token}`});
const currentAnswer=()=>S.session?.tasks[S.taskIndex]?.answers[S.answerIndex];
async function refreshReview(keep=false){try{const s=await api('/api/review/session',{headers:reviewHeaders()});S.session=s;S.review.name=s.name;localStorage.setItem('edubench-review',JSON.stringify(S.review));if(!keep){const i=s.tasks.findIndex(t=>t.answers.some(a=>!a.scores));S.taskIndex=Math.max(0,i);S.answerIndex=Math.max(0,s.tasks[S.taskIndex]?.answers.findIndex(a=>!a.scores)??0);}renderReview();}catch(e){if(e.message.includes('先输入')||e.message.includes('不存在')){localStorage.removeItem('edubench-review');S.review=null;await reviewLogin();}else throw e;}}
function draftKey(c){return `edubench-draft-${S.review.token}-${c.id}`;}
function renderReview(){const s=S.session,task=s.tasks[S.taskIndex],c=currentAnswer(),completed=s.cases.filter(c=>c.scores).length,taskDone=s.tasks.filter(t=>t.answers.every(a=>a.scores)).length;if(!task||!c)return;
 const draft=JSON.parse(localStorage.getItem(draftKey(c))||'null');const scores=draft?.scores||c.scores||{},note=draft?.note??c.note;
 $('#app').innerHTML=reviewFrame(`<main class="review-main"><div class="review-top"><div><div class="eyebrow">BLIND REVIEW · ${esc(s.runName)}</div><h1>我的 ${s.tasks.length} 条评测任务</h1><span class="helper">已完成 ${taskDone} 条任务 · 已评分 ${completed}/${s.totalExpected} 个回答</span></div><div class="review-progress">${progress(completed,s.totalExpected)}<button class="small ghost" data-action="review-refresh">${icon('refresh')} 刷新输出</button></div></div>${s.projects.length>1?`<label class="field">我的评测批次<select id="review-project">${s.projects.map(p=>`<option value="${p.token}" ${p.token===s.runToken?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`:''}<div class="review-task-grid">${s.tasks.map((t,i)=>`<button class="task-button ${i===S.taskIndex?'selected':''}" data-action="select-task" data-index="${i}"><strong>${esc(t.case.id)} · ${esc(t.case.subject)}</strong><span>${esc(t.case.title)}</span><small>${t.answers.filter(a=>a.scores).length}/${t.answers.length} 个回答已评分 ${t.answers.every(a=>a.scores)?'✓':''}</small></button>`).join('')}</div>${completed===s.totalExpected?'<div class="notice info">本批次全部评分已保存，仍可查看和修改自己的评分。</div>':''}<section class="card review-case"><div class="card-header"><h2>${icon('book')}第 ${S.taskIndex+1} / ${s.tasks.length} 条 · 任务要求</h2><span class="tag gray">${esc(task.case.id)}</span></div><div class="card-body"><h2>${esc(task.case.title)}</h2><div class="task-meta"><span class="tag">${esc(task.case.subject)}</span><span class="tag gray">${esc(task.case.stage)}</span><span class="tag blue">${esc(task.case.queryType)}</span></div><p class="helper">${esc(task.case.background)}</p><div class="query">${esc(task.case.requirements||task.case.query)}</div>${task.case.requirements!==task.case.query?`<details><summary>查看原始 Query</summary><div class="query">${esc(task.case.query)}</div></details>`:''}</div></section><div class="answer-tabs">${task.answers.map((a,i)=>`<button class="${i===S.answerIndex?'selected':''}" data-action="select-answer" data-index="${i}">${esc(a.code)} <span>${a.scores?'✓ 已评分':a.status==='done'?'待评分':a.status==='failed'?'生成异常':'待生成'}</span></button>`).join('')}</div><section class="card"><div class="review-output-head"><span>${icon('shield')} ${esc(c.code)} · 匿名模型输出</span><span>请依据内容独立判断</span></div><div class="card-body review-answer-body">${c.status==='done'?markdown(c.content):`<div class="notice ${c.status==='failed'?'error':'info'}">${c.status==='failed'?'该模型回答生成失败，已通知管理员处理。没有有效正文，暂不能评分。':'该模型回答尚未生成完成，请先评其他回答。'}</div>`}</div></section>${c.status==='done'?`<section class="card"><div class="card-header"><div><h2>${icon('settings')}人工评分</h2><p>三个维度分别评 1—3 分：1 分较差，2 分合格，3 分优秀。</p></div>${c.updated?`<span class="saved">${icon('check')} 已提交 ${date(c.updated)}</span>`:''}</div><div class="card-body"><form id="score-form" data-id="${c.id}">${s.dimensions.map((d,i)=>`<div class="rating-card"><div class="rating-title"><span class="count">0${i+1}</span>${esc(d.name)}<span class="helper">${d.weight}%</span></div><div class="rating-options">${d.levels.map((l,j)=>`<label class="rating-option"><input type="radio" name="${d.id}" value="${j+1}" ${scores[d.id]===j+1?'checked':''} required><div><strong>${j+1} 分 · ${['较差','合格','优秀'][j]}</strong><span>${esc(l)}</span></div></label>`).join('')}</div></div>`).join('')}<label class="field">评审意见（选填）<textarea name="note" maxlength="5000" placeholder="记录具体问题或评分依据">${esc(note)}</textarea></label><div id="score-error" class="inline-error" role="alert"></div><div class="review-footer"><span id="draft-state" class="helper">${draft?'本页草稿已保存，尚未提交':'提交后保存至服务端，可刷新或稍后继续'}</span><button class="primary" type="submit">${c.scores?'更新评分并继续':'提交并评下一个回答'} ${icon('arrow')}</button></div></form></div></section>`:''}<div class="actions task-navigation"><button data-action="prev-task" ${S.taskIndex===0?'disabled':''}>上一条任务</button><button data-action="next-task" ${S.taskIndex>=s.tasks.length-1?'disabled':''}>下一条任务</button></div><p class="footnote">每条任务的三个回答以固定随机顺序及匿名编码展示。分数、评测人员与提交时间一并保存。</p></main>`,true);
}
async function joinProject(runToken){const r=await api('/api/review/join',{method:'POST',body:{name:S.review.name,runToken}});S.review=r;S.reviewRunToken=runToken;history.replaceState({},'',`/review?run=${encodeURIComponent(runToken)}`);localStorage.setItem('edubench-review',JSON.stringify(r));await refreshReview();}
async function action(name,el){switch(name){
 case 'close':closeModal();break;
 case 'confirm-action':{const resolve=confirmResolve;confirmResolve=null;closeModal();resolve?.(true);break;}
 case 'refresh':await loadAdmin();toast('进度已更新');break;
 case 'go-rules':go('rules');break;
 case 'go-benchmark':go('benchmark');break;
 case 'configure':closeModal();go('models');break;
 case 'add-person':personModal();break;
 case 'edit-person':personModal(el.dataset.id);break;
 case 'go-personnel':closeModal();go('personnel');break;
 case 'assign-people':await assignmentModal(el.dataset.id);break;
 case 'person-progress':personProgressModal(el.dataset.id);break;
 case 'new-run':newRun();break;
 case 'model':modelModal(el.dataset.id);break;
 case 'test-model':{const original=el.innerHTML;el.disabled=true;el.textContent='真实调用中…';try{const r=await api(`/api/admin/models/${el.dataset.id}/test`,{method:'POST',body:{}});modal('API 真实连接测试',`<div class="notice info">供应商已返回真实响应，耗时 ${num(r.latencyMs/1000)} 秒；Token ${r.usage.total??'未返回'}。</div><div class="code-block">${esc(r.content)}</div><p class="helper">实际型号：${esc(r.model)}</p>`,`<button data-action="close">完成</button>`);}finally{el.disabled=false;el.innerHTML=original;await loadAdmin();}break;}
 case 'case':caseModal(el.dataset.bench,el.dataset.id);break;
 case 'add-case':caseModal(el.dataset.bench);break;
 case 'import':importModal();break;
 case 'rename-bench':{const b=S.admin.benchmarks.find(b=>b.id===el.dataset.id);modal('重命名 Benchmark',`<form id="rename-bench-form" data-id="${b.id}">${field('测试集名称','name',b.name,'text','required')}</form>`,modalButtons('rename-bench-form'));break;}
 case 'edit-rules':rulesModal();break;
 case 'download-bench':{const b=S.admin.benchmarks.find(b=>b.id===el.dataset.id);download('edubench-benchmark.json',b.cases);break;}
 case 'delete-bench':if(await confirmAction('删除此测试集？已创建评测的快照将保留。')){await api(`/api/admin/benchmarks/${el.dataset.id}`,{method:'DELETE'});await loadAdmin();toast('测试集已删除');}break;
 case 'delete-case':{const b=S.admin.benchmarks.find(b=>b.id===el.dataset.bench);if(await confirmAction('删除此 Query？已有任务不受影响。')){await api(`/api/admin/benchmarks/${b.id}`,{method:'PUT',body:{name:b.name,cases:b.cases.filter(c=>c.id!==el.dataset.id)}});closeModal();await loadAdmin();}break;}
 case 'open-run':go('run',el.dataset.id);break;
 case 'analyze':go('analysis',el.dataset.id);break;
 case 'output':outputModal(el.dataset.id);break;
 case 'retry':if(await confirmAction('继续未完成步骤？会产生真实 API 调用费用，已成功的步骤会跳过。')){await api(`/api/admin/runs/${el.dataset.id}/retry`,{method:'POST',body:{}});await loadAdmin();toast('已开始执行未完成步骤');}break;
 case 'delete-run':if(await confirmAction('删除此任务及关联输出、评分？此操作无法撤销。')){await api(`/api/admin/runs/${el.dataset.id}`,{method:'DELETE'});go();}break;
 case 'share':await share();break;
 case 'copy-share':{const input=$('#share-url');input.select();try{await navigator.clipboard.writeText(input.value);toast('评测链接已复制');}catch{toast('请复制已选中的链接');}break;}
 case 'snapshot':modal('本次评测配置快照',`<pre class="code-block">${esc(JSON.stringify({...S.run.snapshot,cases:S.run.snapshot.cases.map(c=>({id:c.id,title:c.title}))},null,2))}</pre>`,`<button data-action="close">关闭</button>`,true);break;
 case 'download-results':download(`edubench-${S.run.id}.json`,S.run);break;
 case 'report':go('report',S.run.id);break;
 case 'print':window.print();break;
 case 'review-logout':localStorage.removeItem('edubench-review');S.review=null;await reviewLogin();break;
 case 'review-refresh':await refreshReview(true);break;
 case 'select-task':S.taskIndex=Number(el.dataset.index);S.answerIndex=0;renderReview();break;
 case 'select-answer':S.answerIndex=Number(el.dataset.index);renderReview();break;
 case 'prev-task':S.taskIndex--;S.answerIndex=0;renderReview();window.scrollTo({top:0,behavior:'smooth'});break;
 case 'next-task':S.taskIndex++;S.answerIndex=0;renderReview();window.scrollTo({top:0,behavior:'smooth'});break;
 }}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{await action(el.dataset.action,el);}catch(err){toast(err.message);if($('#form-error'))$('#form-error').textContent=err.message;}return;}
 const a=e.target.closest('a');if(a&&a.origin===location.origin&&a.pathname==='/admin'&&!a.target&&!e.metaKey&&!e.ctrlKey){e.preventDefault();const u=new URL(a.href);go(u.searchParams.get('tab')||'overview',u.searchParams.get('id'));}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
document.addEventListener('change',e=>{if(e.target.id==='run-select')go(S.tab,e.target.value);if(e.target.classList.contains('metric-select')){S.metric=e.target.value;renderAdmin();}if(e.target.id==='review-project'){joinProject(e.target.value).catch(err=>toast(err.message));}if(e.target.id==='group-select'){S.group=e.target.value;renderAdmin();}});
document.addEventListener('input',e=>{if(e.target.closest('#score-form')){const f=new FormData($('#score-form'));const c=currentAnswer();const scores=Object.fromEntries(S.session.dimensions.filter(d=>f.get(d.id)).map(d=>[d.id,Number(f.get(d.id))]));localStorage.setItem(draftKey(c),JSON.stringify({scores,note:f.get('note')}));$('#draft-state').textContent='本页草稿已保存，提交后计入评测结果';}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form);const submit=document.querySelector(`[form="${form.id}"][type="submit"]`)||form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
 try{
  if(form.id==='person-form'){await api('/api/admin/personnel'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:{name:f.get('name')}});closeModal();await loadAdmin();toast('评测人员已保存');}
  if(form.id==='assignment-form'){await api(`/api/admin/runs/${form.dataset.id}/reviewers`,{method:'PUT',body:{personIds:f.getAll('personIds')}});closeModal();await loadAdmin();toast('人员分配已保存');}
  if(form.id==='model-form'){await api(`/api/admin/models/${form.dataset.id}`,{method:'PUT',body:{name:f.get('name'),protocol:f.get('protocol'),model:f.get('model').trim(),baseUrl:f.get('baseUrl').trim(),apiKey:f.get('apiKey'),clearKey:f.has('clearKey'),temperature:Number(f.get('temperature')),maxTokens:Number(f.get('maxTokens')),timeoutMs:Number(f.get('timeout'))*1000}});closeModal();await loadAdmin();toast('API 配置已保存');}
  if(form.id==='run-form'){const r=await api('/api/admin/runs',{method:'POST',body:Object.fromEntries(f)});closeModal();go('run',r.id);}
  if(form.id==='case-form'){const b=S.admin.benchmarks.find(b=>b.id===form.dataset.bench);const c=Object.fromEntries(f);c.scenario=c.category;const cases=form.dataset.id?b.cases.map(x=>x.id===form.dataset.id?c:x):[...b.cases,c];await api(`/api/admin/benchmarks/${b.id}`,{method:'PUT',body:{name:b.name,cases}});closeModal();await loadAdmin();toast('Query 已保存');}
  if(form.id==='rename-bench-form'){const b=S.admin.benchmarks.find(b=>b.id===form.dataset.id);await api(`/api/admin/benchmarks/${b.id}`,{method:'PUT',body:{name:f.get('name'),cases:b.cases}});closeModal();await loadAdmin();toast('名称已更新');}
  if(form.id==='import-form'){const file=f.get('file');const content=await file.text();const format=file.name.toLowerCase().endsWith('.csv')?'csv':'json';let cases;if(format==='json'){const parsed=JSON.parse(content);cases=Array.isArray(parsed)?parsed:parsed.cases;}await api('/api/admin/benchmarks',{method:'POST',body:{name:f.get('name'),format,content,cases}});closeModal();await loadAdmin();toast('Benchmark 已导入');}
  if(form.id==='rules-form'){const dimensions=S.admin.dimensions.map(d=>({...d,name:f.get(d.id+'_name'),focus:f.get(d.id+'_focus'),weight:Number(f.get(d.id+'_weight')),levels:[0,1,2].map(i=>f.get(d.id+'_'+i))}));await api('/api/admin/dimensions',{method:'PUT',body:{dimensions}});closeModal();await loadAdmin();toast('评分规则已保存');}
  if(form.id==='join-form'){const r=await api('/api/review/join',{method:'POST',body:Object.fromEntries(f)});S.review=r;localStorage.setItem('edubench-review',JSON.stringify(r));await refreshReview();}
  if(form.id==='score-form'){const c=currentAnswer();const scores=Object.fromEntries(S.session.dimensions.map(d=>[d.id,Number(f.get(d.id))]));await api('/api/review/score',{method:'POST',headers:reviewHeaders(),body:{outputId:c.id,scores,note:f.get('note')}});localStorage.removeItem(draftKey(c));await refreshReview(true);const task=S.session.tasks[S.taskIndex];const ai=task.answers.findIndex(a=>!a.scores&&a.status==='done');if(ai>=0)S.answerIndex=ai;else{const ti=S.session.tasks.findIndex((t,i)=>i>S.taskIndex&&t.answers.some(a=>!a.scores&&a.status==='done'));if(ti>=0){S.taskIndex=ti;S.answerIndex=S.session.tasks[ti].answers.findIndex(a=>!a.scores&&a.status==='done');}}renderReview();toast('评分已保存到服务端');window.scrollTo({top:0,behavior:'smooth'});}
 }catch(err){const target=form.id==='join-form'?$('#join-error'):form.id==='score-form'?$('#score-error'):$('#form-error');if(target)target.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}
});
window.addEventListener('popstate',()=>boot());
async function boot(){try{if(location.pathname.startsWith('/review'))await loadReview();else{const q=new URLSearchParams(location.search);S.tab=q.get('tab')||'overview';if(!['overview','benchmark','models','rules','personnel','run','analysis','report'].includes(S.tab))S.tab='overview';S.id=q.get('id');await loadAdmin();}}catch(e){toast(e.message);$('#app').innerHTML=reviewFrame(`<div class="review-login"><h1>页面加载失败</h1><p>${esc(e.message)}</p><a class="linkbtn" href="${location.pathname.startsWith('/review')?'/review':'/admin'}">重新进入</a></div>`);}}
setInterval(async()=>{if(document.hidden||S.polling||$('#modal-root').innerHTML)return;S.polling=true;try{if(location.pathname.startsWith('/review')){if(S.review&&S.session){const next=await api('/api/review/session',{headers:reviewHeaders()});const changed=JSON.stringify(next.tasks.map(t=>t.answers.map(a=>a.status)))!==JSON.stringify(S.session.tasks.map(t=>t.answers.map(a=>a.status)))||next.name!==S.session.name;S.session=next;S.review.name=next.name;if(changed)renderReview();}}else if(S.admin?.runs.some(r=>r.active)||S.run){await loadAdmin(true);}}catch(e){if(location.pathname.startsWith('/review')&&e.message.includes('先输入')){S.review=null;localStorage.removeItem('edubench-review');await reviewLogin();toast('当前任务分配已收回，请联系管理员');}}finally{S.polling=false;}},3000);
boot();
